
create table public.resource_categories(id uuid primary key default gen_random_uuid(),name text not null unique check(btrim(name)<>''));
create table public.resource_contacts(id uuid primary key default gen_random_uuid(),name text not null check(btrim(name)<>''),organisation text,phone text,email text,profile_id uuid references public.profiles(id) on delete set null,active boolean not null default true);
create table public.resource_places(id uuid primary key default gen_random_uuid(),location_id bigint not null references public.locations(id),parent_id uuid references public.resource_places(id),name text not null check(btrim(name)<>''),unique nulls not distinct(location_id,parent_id,name));
create table public.resources(id uuid primary key default gen_random_uuid(),name text not null check(btrim(name)<>''),category_id uuid references public.resource_categories(id),description text);
create table public.resource_stocks(id uuid primary key default gen_random_uuid(),resource_id uuid not null references public.resources(id),place_id uuid not null references public.resource_places(id),manager_id uuid not null references public.resource_contacts(id),owner_name text not null check(btrim(owner_name)<>''),quantity integer not null check(quantity>=0),condition text not null default 'Gebrauchsfähig',bookable boolean not null default true,approval_required boolean not null default true,fee numeric(10,2) not null default 0 check(fee>=0),notes text);
create table public.resource_movements(id uuid primary key default gen_random_uuid(),source_id uuid references public.resource_stocks(id),target_id uuid references public.resource_stocks(id),quantity integer not null check(quantity>0),kind text not null,actor uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),notes text);
alter table public.resource_categories enable row level security; revoke all on public.resource_categories from public,anon,authenticated; grant select on public.resource_categories to authenticated; create policy member_read on public.resource_categories for select to authenticated using ((select public.is_active_member()));
alter table public.resource_contacts enable row level security; revoke all on public.resource_contacts from public,anon,authenticated; grant select on public.resource_contacts to authenticated; create policy member_read on public.resource_contacts for select to authenticated using ((select public.is_active_member()));
alter table public.resource_places enable row level security; revoke all on public.resource_places from public,anon,authenticated; grant select on public.resource_places to authenticated; create policy member_read on public.resource_places for select to authenticated using ((select public.is_active_member()));
alter table public.resources enable row level security; revoke all on public.resources from public,anon,authenticated; grant select on public.resources to authenticated; create policy member_read on public.resources for select to authenticated using ((select public.is_active_member()));
alter table public.resource_stocks enable row level security; revoke all on public.resource_stocks from public,anon,authenticated; grant select on public.resource_stocks to authenticated; create policy member_read on public.resource_stocks for select to authenticated using ((select public.is_active_member()));
alter table public.resource_movements enable row level security; revoke all on public.resource_movements from public,anon,authenticated; grant select on public.resource_movements to authenticated; create policy member_read on public.resource_movements for select to authenticated using ((select public.is_active_member()));
grant insert on public.resource_categories to authenticated; create policy admin_insert on public.resource_categories for insert to authenticated with check ((select public.is_admin()));
grant insert on public.resource_contacts to authenticated; create policy admin_insert on public.resource_contacts for insert to authenticated with check ((select public.is_admin()));
grant insert on public.resource_places to authenticated; create policy admin_insert on public.resource_places for insert to authenticated with check ((select public.is_admin()));
grant insert on public.resources to authenticated; create policy admin_insert on public.resources for insert to authenticated with check ((select public.is_admin()));
create function public.resource_place_check() returns trigger language plpgsql set search_path='' as $$begin if new.parent_id is not null and not exists(select 1 from public.resource_places where id=new.parent_id and location_id=new.location_id) then raise exception 'Ungültiger übergeordneter Lagerort'; end if; return new; end$$;
create trigger resource_place_check before insert on public.resource_places for each row execute function public.resource_place_check();
create function public.resource_add_stock(p_resource uuid,p_place uuid,p_manager uuid,p_owner text,p_qty integer,p_condition text,p_bookable boolean,p_approval boolean,p_fee numeric,p_notes text) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid; begin if auth.uid() is null or not public.is_admin() then raise exception 'Keine Berechtigung'; end if; if p_qty is null or p_qty<=0 or not exists(select 1 from public.resource_contacts where id=p_manager and active) then raise exception 'Menge oder Verwalter ungültig'; end if; insert into public.resource_stocks(resource_id,place_id,manager_id,owner_name,quantity,condition,bookable,approval_required,fee,notes) values(p_resource,p_place,p_manager,p_owner,p_qty,p_condition,p_bookable,p_approval,p_fee,p_notes) returning id into v; insert into public.resource_movements(target_id,quantity,kind,actor,notes) values(v,p_qty,'Zugang',auth.uid(),p_notes); return v; end$$;
create function public.resource_move(p_stock uuid,p_place uuid,p_qty integer,p_manager uuid default null,p_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$declare s public.resource_stocks%rowtype; v uuid; begin if auth.uid() is null or not public.is_active_member() then raise exception 'Keine Berechtigung'; end if; select * into strict s from public.resource_stocks where id=p_stock for update; if not public.is_admin() and not exists(select 1 from public.resource_contacts where id=s.manager_id and profile_id=auth.uid() and active) then raise exception 'Keine Berechtigung'; end if; if p_qty is null or p_qty<=0 or p_qty>s.quantity then raise exception 'Ungültige Menge'; end if; if p_manager is not null and not exists(select 1 from public.resource_contacts where id=p_manager and active) then raise exception 'Ungültiger Verwalter'; end if; if p_place=s.place_id and coalesce(p_manager,s.manager_id)=s.manager_id then raise exception 'Keine Änderung'; end if; update public.resource_stocks set quantity=quantity-p_qty where id=s.id; insert into public.resource_stocks(resource_id,place_id,manager_id,owner_name,quantity,condition,bookable,approval_required,fee,notes) values(s.resource_id,p_place,coalesce(p_manager,s.manager_id),s.owner_name,p_qty,s.condition,s.bookable,s.approval_required,s.fee,s.notes) returning id into v; insert into public.resource_movements(source_id,target_id,quantity,kind,actor,notes) values(s.id,v,p_qty,case when p_place=s.place_id then 'Verantwortungswechsel' else 'Umlagerung' end,auth.uid(),p_notes); return v; end$$;
revoke all on function public.resource_add_stock(uuid,uuid,uuid,text,integer,text,boolean,boolean,numeric,text),public.resource_move(uuid,uuid,integer,uuid,text) from public,anon,authenticated;
grant execute on function public.resource_add_stock(uuid,uuid,uuid,text,integer,text,boolean,boolean,numeric,text),public.resource_move(uuid,uuid,integer,uuid,text) to authenticated;
insert into public.resource_categories(name) values ('Veranstaltungsausstattung'),('Technik'),('Werkzeuge'),('Transport'),('Räumlichkeiten'),('Geschirr und Zubehör'),('Sonstiges');
